/* BoniVerso • RSB Educação | MVP demonstrativo local (sem autenticação ou cobrança reais) */
(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const KEY = 'boniverso-preview-v2';
  const TODAY = new Date();
  const inDays = n => { const d = new Date(); d.setDate(d.getDate()+n); return d.toISOString().slice(0,10); };
  const money = x => Number(x||0).toLocaleString('pt-BR', {style:'currency',currency:'BRL'});
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const slug = s => String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const uid = () => typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Date.now().toString(36)+Math.random().toString(36).slice(2);
  const dateBR = s => { if (!s) return 'Sem prazo'; const [y,m,d] = s.split('-'); return `${d}/${m}/${y}`; };
  const cssColors = [ ['#FFE6E6','#F7B9C5','#C7546D'], ['#DEECFF','#9FC3FF','#2D69CA'], ['#FFF0C7','#F4C87F','#A87925'], ['#DFF4EE','#9EDFCB','#21866C'], ['#EDE7FF','#BEA8F5','#7B58C3'] ];
  const icons = {
    home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
    book:'<path d="M12 7v14M12 7C9.7 4.8 6.5 4 2 4v15c4.5 0 7.7.8 10 2M12 7c2.3-2.2 5.5-3 10-3v15c-4.5 0-7.7.8-10 2"/>',
    clipboard:'<rect x="5" y="4" width="14" height="18" rx="2"/><path d="M9 4.5h6M8 11h8M8 15h5"/>',
    check:'<path d="m4 12 5 5L20 6"/>',
    calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',
    chart:'<path d="M4 20V11m5 9V4m5 16v-6m5 6V8"/>',
    pen:'<path d="m12 19-8 2 2-8L17 2l5 5zM14 5l5 5"/>',
    profile:'<circle cx="12" cy="8" r="4"/><path d="M4 22c0-5 3-8 8-8s8 3 8 8"/>',
    crown:'<path d="m2 8 5 4 5-8 5 8 5-4-2 12H4z"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
    search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',
    bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 8-3 10h18c0-2-3-3-3-10ZM10 21h4"/>',
    arrow:'<path d="M4 12h16m-7-7 7 7-7 7"/>',
    chevron:'<path d="m9 18 6-6-6-6"/>',
    close:'<path d="M5 5 19 19M19 5 5 19"/>',
    play:'<path d="m8 5 11 7-11 7z"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
    file:'<path d="M7 2h8l5 5v15H7a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2Zm8 0v6h5M9 13h7m-7 4h7"/>',
    people:'<circle cx="8" cy="8" r="3"/><path d="M2 20v-2a6 6 0 0 1 12 0v2M17 5a3 3 0 0 1 0 6m-1 3a6 6 0 0 1 6 6"/>',
    settings:'<path d="M12 3v3m0 12v3M3 12h3m12 0h3m-15-6 2.2 2.2m7.6 7.6L18 18M18 6l-2.2 2.2M8.2 15.8 6 18"/><circle cx="12" cy="12" r="4"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    download:'<path d="M12 3v13m-5-5 5 5 5-5M4 19v2h16v-2"/>',
    upload:'<path d="M12 21V8m-5 5 5-5 5 5M4 5V3h16v2"/>',
    edit:'<path d="m3 17 11-11 4 4L7 21H3zm13-13 3-2 3 3-2 3"/>',
    award:'<circle cx="12" cy="8" r="5"/><path d="m8 12-2 9 6-3 6 3-2-9"/>',
    lock:'<rect x="5" y="11" width="14" height="11" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/>',
    globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-4 4-4 14 0 18m0-18c4 4 4 14 0 18"/>',
    credit:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20m-16 5h5"/>',
    star:'<path d="m12 2 3.2 6.5 7.1 1-5.1 5 1.2 7-6.4-3.4-6.4 3.4 1.2-7-5.1-5 7.1-1z"/>',
    external:'<path d="M13 4h7v7m0-7-10 10M20 14v5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h5"/>',
    save:'<path d="M4 3h13l4 4v14H4zM8 3v7h9V3M8 21v-8h9v8"/>',
    info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10v1"/>'
  };
  const ic = (n, size=18) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.star}</svg>`;
  const c0 = [
    {id:'redacao',title:'Redação ENEM: do zero à nota 1000',category:'Redação',description:'Domine a estrutura do texto dissertativo-argumentativo, repertórios e proposta de intervenção.',color:0,level:'Todos os níveis',duration:'12 horas',price:149.9,lessons:[{id:'r1',title:'Tema, tese e argumento',duration:'18 min',videoUrl:'',resources:[]},{id:'r2',title:'Os quatro parágrafos da redação',duration:'25 min',videoUrl:'',resources:[]},{id:'r3',title:'Proposta de intervenção: os cinco elementos',duration:'22 min',videoUrl:'',resources:[]}]},
    {id:'portugues',title:'Português sem complicação',category:'Língua Portuguesa',description:'Classes gramaticais, sintaxe, concordância e interpretação textual na prática.',color:1,level:'Intermediário',duration:'10 horas',price:119.9,lessons:[{id:'p1',title:'Classes de palavras na prática',duration:'20 min',videoUrl:'',resources:[]},{id:'p2',title:'Concordância verbal e nominal',duration:'24 min',videoUrl:'',resources:[]},{id:'p3',title:'Interpretação de textos',duration:'30 min',videoUrl:'',resources:[]}]},
    {id:'literatura',title:'Literatura brasileira essencial',category:'Literatura',description:'Movimentos literários, obras e autores mais cobrados nos exames.',color:2,level:'Todos os níveis',duration:'8 horas',price:99.9,lessons:[{id:'l1',title:'Do Romantismo ao Realismo',duration:'19 min',videoUrl:'',resources:[]},{id:'l2',title:'Modernismo e Semana de 22',duration:'27 min',videoUrl:'',resources:[]}]},
    {id:'gramatica',title:'Gramática para provas e concursos',category:'Gramática',description:'Reforce as regras com questões comentadas e exemplos do cotidiano.',color:3,level:'Intermediário',duration:'9 horas',price:109.9,lessons:[{id:'g1',title:'Crase com segurança',duration:'21 min',videoUrl:'',resources:[]},{id:'g2',title:'Pontuação e sentido',duration:'22 min',videoUrl:'',resources:[]}]},
    {id:'repertorios',title:'Repertórios para argumentar melhor',category:'Redação',description:'Referências históricas e culturais para enriquecer seus argumentos.',color:4,level:'Todos os níveis',duration:'6 horas',price:79.9,lessons:[{id:'rr1',title:'Como usar repertórios sem decorar',duration:'16 min',videoUrl:'',resources:[]}]}
  ];
  const demoQuiz = [
    {id:'q1',category:'Redação',q:'Em um texto dissertativo-argumentativo, a tese corresponde a:',options:['Um exemplo usado no desenvolvimento.','O posicionamento central defendido no texto.','A proposta de intervenção completa.','Uma citação de autoridade.'],answer:1,explain:'A tese é a posição do autor sobre o tema e orienta os argumentos.'},
    {id:'q2',category:'Redação',q:'Qual elemento da conclusão do ENEM indica quem executará a ação proposta?',options:['Agente.','Meio.','Finalidade.','Detalhamento.'],answer:0,explain:'O agente indica quem deverá realizar a medida proposta.'},
    {id:'q3',category:'Língua Portuguesa',q:'Assinale a frase com concordância verbal adequada à norma-padrão:',options:['Fazem dois anos que estudo.','Houveram muitos candidatos.','Faz dois anos que estudo.','Existe muitos temas.'],answer:2,explain:'O verbo fazer indicando tempo decorrido é impessoal e fica na 3ª pessoa do singular.'},
    {id:'q4',category:'Gramática',q:'Em qual opção o uso de crase está correto?',options:['Fui à escola estudar.','Entreguei o texto à Rafael.','Comecei à escrever.','Viajei à pé.'],answer:0,explain:'Há fusão da preposição a com o artigo feminino a antes de “escola”.'},
    {id:'q5',category:'Literatura',q:'O Realismo brasileiro é frequentemente associado a qual autor?',options:['José de Alencar.','Machado de Assis.','Castro Alves.','Gonçalves Dias.'],answer:1,explain:'Machado de Assis é um dos principais autores do Realismo brasileiro.'},
    {id:'q6',category:'Redação',q:'Um repertório sociocultural produtivo na redação deve:',options:['Ser longo, mesmo sem conexão temática.','Substituir os argumentos do autor.','Estar relacionado e contribuir para a argumentação.','Ser obrigatoriamente uma citação literal.'],answer:2,explain:'O repertório precisa estar articulado à discussão e ter função argumentativa.'}
  ];
  const initial = () => ({
    version:2, role:'student', view:'home', name:'Estudante BoniVerso', email:'', plan:'Básico', courses:c0, enrollments:['redacao','portugues'], completed:['r1'],
    tasks:[{id:'t1',title:'Revisar a estrutura da redação',due:inDays(1),done:false,category:'Redação'},{id:'t2',title:'Resolver questões de gramática',due:inDays(2),done:false,category:'Gramática'},{id:'t3',title:'Assistir à aula: tema e tese',due:inDays(-1),done:true,category:'Redação'},{id:'t4',title:'Produzir uma redação sobre educação',due:inDays(5),done:false,category:'Redação'}],
    assignments:[{id:'a1',title:'Redação da semana: educação e tecnologia',category:'Redação',due:inDays(5),description:'Produza um texto dissertativo-argumentativo de até 30 linhas com uma proposta de intervenção.',points:1000},{id:'a2',title:'Revisão: concordância verbal',category:'Gramática',due:inDays(7),description:'Responda às questões propostas no material da aula.',points:100}],
    submissions:[{id:'s1',assignmentId:'a1',student:'Aluno de demonstração',text:'A tecnologia transformou os modos de aprender. Entretanto, o acesso desigual aos recursos digitais cria dificuldades para parcela dos estudantes. É necessário investir em infraestrutura e formação docente para promover o aprendizado de forma inclusiva.',sent:inDays(-2),status:'pending',grade:null,feedback:'',competencies:[0,0,0,0,0]}],
    quizzes:demoQuiz, quizResults:[], notifications:[], fileMeta:[]
  });
  const readState = () => { try {const raw = JSON.parse(localStorage.getItem(KEY)); if(raw && raw.version===2 && Array.isArray(raw.courses)) return raw;} catch {} return initial(); };
  let state = readState();
  let activeQuiz = null;
  let courseFilter = 'Todos';
  let searchValue = '';
  function save() { try {localStorage.setItem(KEY,JSON.stringify(state));} catch(e){toast('Limite de armazenamento local atingido.');} }
  function update(fn) {fn(); save(); render();}
  function toast(msg) { const target=$('#toasts'); const node=document.createElement('div'); node.className='toast'; node.textContent=msg; target.append(node); setTimeout(()=>node.remove(),3800); }
  const navStudent = [['home','Início','home'],['courses','Meus cursos','book'],['planner','Plano de estudos','calendar'],['quizzes','Questões','clipboard'],['essays','Redações','pen'],['performance','Desempenho','chart'],['plans','Assinaturas','crown'],['profile','Meu perfil','profile']];
  const navTeacher = [['admin','Visão geral','home'],['manage-courses','Gerenciar cursos','book'],['manage-tasks','Atividades e prazos','clipboard'],['corrections','Corrigir redações','pen'],['students','Estudantes','people'],['finance','Planos e vendas','credit'],['profile','Meu perfil','profile']];
  const menuForRole = () => state.role==='teacher' ? navTeacher : navStudent;
  const viewTitle = () => (menuForRole().find(v=>v[0]===state.view)||menuForRole()[0])[1];
  const countDone = () => state.tasks.filter(t=>t.done).length;
  const pct = (num,den) => den ? Math.round(num/den*100) : 0;
  const teacherBanner = () => `<div class="teacher-banner">${ic('info')} <span><b>Ambiente do professor — demonstração.</b> Alterações são salvas apenas neste navegador; alunos reais não recebem as publicações.</span></div>`;
  const chip = (label,variant='') => `<span class="tag ${variant}">${esc(label)}</span>`;
  const hTop = (eyebrow,title,subtitle='',right='') => `<div class="page-top"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${right}</div>`;
  const empty = (title,desc='',action='') => `<div class="empty">${ic('book',38)}<h3>${esc(title)}</h3><p>${esc(desc)}</p>${action}</div>`;
  const btn = (label,action,extra='',icon='') => `<button class="btn ${extra}" data-action="${esc(action)}">${icon?ic(icon):''}${esc(label)}</button>`;
  function stats() { return { courses:state.enrollments.length,done:state.completed.length,exercises:state.quizResults.length, tasks:pct(countDone(),state.tasks.length)}; }
  function courseArt(c) { const [a,b,f]=cssColors[(c.color||0)%cssColors.length]; return `<div class="course-art" style="--art1:${a};--art2:${b};--art3:${f}"><span class="art-corner">${esc(c.category)}</span><div class="art-symbol">${ic(c.category==='Redação'?'pen':c.category==='Literatura'?'book':c.category==='Gramática'?'clipboard':'book',34)}</div></div>`; }
  function courseProgress(c){return pct(c.lessons.filter(l=>state.completed.includes(l.id)).length,c.lessons.length);}
  function courseCard(c){const owned=state.enrollments.includes(c.id);const prog=courseProgress(c);return `<article class="course-card">${courseArt(c)}<div class="course-content"><small>${esc(c.level)}</small><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="course-meta"><span>${ic('clock')} ${esc(c.duration)}</span><span>${ic('play')} ${c.lessons.length} aulas</span></div>${owned?`<div class="progress-track" style="margin-top:13px"><div class="progress-fill" style="width:${prog}%"></div></div><div class="progress-text">${prog}% concluído</div>`:''}<div class="course-footer">${chip(owned?'Em andamento':money(c.price),owned?'green':'gold')}<button class="btn btn-sm" data-action="course" data-id="${esc(c.id)}">${owned?'Continuar':'Detalhes'} ${ic('chevron',14)}</button></div></div></article>`;}
  function home() {
    const courses = state.courses.filter(c=>state.enrollments.includes(c.id)).slice(0,3), s=stats(), next=state.tasks.filter(t=>!t.done).slice(0,4);
    return `<div class="hero"><div class="hero-orbit"></div><div class="hero-star">✦</div><div class="hero-copy"><div class="hero-eyebrow">SEU UNIVERSO DE CONHECIMENTO</div><h1>Aprenda mais.<br><em>Vá mais longe.</em></h1><p>Redação, língua portuguesa e literatura com o Prof. Rafa Boni. Seu próximo capítulo começa aqui.</p><div class="hero-actions">${btn('Continuar estudando','go-courses','','play')}${btn('Ver planejamento','go-planner','btn-outline','calendar')}</div></div><img class="hero-portrait" src="rafa-boni-cutout.png" alt="Prof. Rafael Bonifácio"/><div class="hero-tag">PROF. RAFA BONI</div></div>
      <div class="stats-row">${stat('Cursos iniciados',s.courses,'book','blue')}${stat('Aulas concluídas',s.done,'check','green')}${stat('Simulados feitos',s.exercises,'clipboard','gold')}${stat('Plano concluído',s.tasks+'%','chart','rose')}</div>
      <div class="section"><div class="section-head"><div><h2 class="section-title">Continue de onde parou</h2><p class="section-subtitle">Seu aprendizado está sempre por perto.</p></div><button class="link-action" data-action="go-courses">Ver todos ${ic('arrow',13)}</button></div><div class="course-grid">${courses.map(courseCard).join('')}</div></div>
      <div class="body-grid section"><div class="panel"><div class="section-head"><div><h2 class="section-title">Seu plano da semana</h2><p class="section-subtitle">Pequenas metas, grandes conquistas.</p></div><button class="link-action" data-action="go-planner">Abrir plano</button></div>${next.length?next.map(t=>taskRow(t)).join(''):empty('Tudo em dia!','Você já concluiu as tarefas cadastradas.')}</div><div class="panel"><div class="section-head"><div><h2 class="section-title">Sua evolução</h2><p class="section-subtitle">Um passo por vez.</p></div></div><div class="progress-card"><div class="donut" style="--pct:${s.tasks}%"><div class="donut-inner"><b>${s.tasks}%</b><small>do plano</small></div></div><div><h3>Você está evoluindo!</h3><p class="muted">Acompanhe o que já realizou e descubra seu próximo objetivo.</p><button class="link-action" data-action="go-performance">Ver desempenho ${ic('arrow',13)}</button></div></div><div class="callout gold" style="margin-top:17px">✦ Seu futuro é construído por cada página estudada.</div></div></div>`;
  }
  function stat(label,value,icon,color){return `<div class="stat-card"><span class="stat-icon ${color}">${ic(icon)}</span><div><small>${esc(label)}</small><b>${esc(value)}</b></div></div>`;}
  function courses() { let list=state.courses.filter(c=>(courseFilter==='Todos'||c.category===courseFilter) && slug(c.title+' '+c.description+' '+c.category).includes(slug(searchValue)));const cats=['Todos',...new Set(state.courses.map(c=>c.category))];return `${hTop('SUA BIBLIOTECA','Explore os cursos','Aprenda no seu ritmo, onde e quando quiser.')}
    <div class="filter-row"><input class="inline-search" id="courseSearch" placeholder="Buscar por curso ou disciplina..." value="${esc(searchValue)}" aria-label="Buscar cursos"/>${cats.map(c=>`<button class="pill ${courseFilter===c?'active':''}" data-action="filter" data-id="${esc(c)}">${esc(c)}</button>`).join('')}</div>
    ${list.length?`<div class="course-grid">${list.map(courseCard).join('')}</div>`:empty('Nenhum curso encontrado','Tente outro nome ou disciplina.')}
    <div class="callout section">${ic('info',18)} Nesta demonstração, alguns cursos estão liberados para exploração. Aulas gravadas e pagamentos reais serão conectados na etapa de produção.</div>`; }
  function taskRow(t) {const late=!t.done&&t.due&&t.due<inDays(0);return `<div class="task-row"><input class="task-check" type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''} aria-label="Concluir ${esc(t.title)}"/><div class="task-detail"><strong style="${t.done?'text-decoration:line-through;color:#9DA8B8':''}">${esc(t.title)}</strong><small>${esc(t.category||'Estudos')} · ${dateBR(t.due)} ${late?'<span style="color:#DD795E">• Atrasada</span>':''}</small></div>${t.done?chip('Concluída','green'):chip(late?'Atrasada':'Pendente',late?'rose':'gold')}</div>`;}
  function planner(){const todo=state.tasks.filter(t=>!t.done),done=state.tasks.filter(t=>t.done);return `${hTop('ORGANIZAÇÃO','Meu plano de estudos','Defina objetivos e acompanhe suas tarefas.',btn('Nova tarefa','new-task','','plus'))}<div class="stats-row">${stat('Tarefas no plano',state.tasks.length,'clipboard','blue')}${stat('Concluídas',done.length,'check','green')}${stat('Pendentes',todo.length,'clock','gold')}${stat('Progresso',pct(done.length,state.tasks.length)+'%','chart','rose')}</div><div class="two-cols"><section class="panel"><div class="section-head"><h2 class="section-title">Próximas tarefas</h2></div>${todo.length?todo.map(taskRow).join(''):empty('Sem tarefas pendentes','Adicione uma meta para esta semana.')}</section><section class="panel"><div class="section-head"><h2 class="section-title">Concluídas</h2></div>${done.length?done.map(taskRow).join(''):empty('Seu histórico começa aqui','Marque tarefas como concluídas para vê-las nesta lista.')}</section></div>`;}
  function quizzes(){const total=state.quizResults.length;return `${hTop('PRATIQUE','Banco de questões','Teste seus conhecimentos em português, gramática, literatura e redação.')}
      <div class="stats-row">${stat('Questões disponíveis',state.quizzes.length,'clipboard','blue')}${stat('Simulados realizados',total,'check','green')}${stat('Melhor nota',total?Math.max(...state.quizResults.map(x=>x.pct))+'%':'—','award','gold')}${stat('Disciplinas',new Set(state.quizzes.map(x=>x.category)).size,'book','rose')}</div>
      <div class="feature-grid">${['Todas','Redação','Língua Portuguesa','Gramática','Literatura'].map((category,index)=>`<div class="feature-item">${ic(index%2?'pen':'clipboard',27)}<h3>${esc(category==='Todas'?'Simulado geral':category)}</h3><p>${state.quizzes.filter(q=>category==='Todas'||q.category===category).length} questões comentadas para praticar.</p><button class="btn" data-action="start-quiz" data-id="${esc(category)}">${ic('play')} Iniciar quiz</button></div>`).join('')}</div>
      ${total?`<div class="panel section"><h2 class="section-title">Histórico de simulados</h2><div class="site-table-wrap"><table class="small-table"><thead><tr><th>Disciplina</th><th>Acertos</th><th>Nota</th><th>Data</th></tr></thead><tbody>${state.quizResults.slice().reverse().slice(0,6).map(r=>`<tr><td>${esc(r.category)}</td><td>${r.correct}/${r.total}</td><td>${r.pct}%</td><td>${dateBR(r.date)}</td></tr>`).join('')}</tbody></table></div></div>`:''}`;}
  function essays(){const mine=state.submissions.filter(s=>s.student!=='Aluno de demonstração');return `${hTop('SUA PRODUÇÃO','Oficina de redação','Escreva, envie e acompanhe seus textos.',btn('Escrever redação','new-essay','','pen'))}<div class="callout gold">${ic('star',18)} As notas desta versão são registradas localmente pelo perfil de professor demonstrativo. Nenhum texto é enviado a um corretor real.</div><div class="two-cols section"><section class="panel"><div class="section-head"><h2 class="section-title">Propostas de produção</h2></div>${state.assignments.map(a=>`<div class="task-row"><span class="stat-icon rose">${ic('pen')}</span><div class="task-detail"><strong>${esc(a.title)}</strong><small>Entrega até ${dateBR(a.due)} · ${esc(a.category)}</small></div><button class="btn btn-sm" data-action="essay-for" data-id="${esc(a.id)}">Escrever</button></div>`).join('')}</section><section class="panel"><div class="section-head"><h2 class="section-title">Minhas entregas</h2></div>${mine.length?mine.map(s=>submissionCard(s)).join(''):empty('Nenhuma redação enviada','Escolha uma proposta para começar sua primeira produção.')}</section></div>`;}
  function submissionCard(s,teacher=false){const a=state.assignments.find(a=>a.id===s.assignmentId);return `<article class="submission-card"><header><h3>${esc(a?.title||'Redação livre')}</h3>${chip(s.status==='graded'?'Corrigida':'Aguardando correção',s.status==='graded'?'green':'gold')}</header><p>${esc(s.text.slice(0,200))}${s.text.length>200?'…':''}</p><p style="margin-top:8px"><b>${teacher?esc(s.student)+' · ':''}${dateBR(s.sent)}</b>${s.status==='graded'?` · <b>Nota: ${s.grade}/1000</b>`:''}</p>${s.feedback?`<div class="callout section">${esc(s.feedback)}</div>`:''}${teacher?`<button class="btn btn-sm" style="margin-top:10px" data-action="grade" data-id="${esc(s.id)}">${ic('edit')} Corrigir texto</button>`:''}</article>`;}
  function performance(){const s=stats();const completed=state.quizResults;const average=completed.length?Math.round(completed.reduce((a,b)=>a+b.pct,0)/completed.length):null;return `${hTop('RESULTADOS','Meu desempenho','Visualize seu progresso nos estudos e nas atividades.')}
      <div class="stats-row">${stat('Aulas concluídas',s.done,'check','green')}${stat('Tarefas concluídas',countDone(),'clipboard','blue')}${stat('Média de acertos',average===null?'—':average+'%','chart','gold')}${stat('Redações corrigidas',state.submissions.filter(x=>x.status==='graded'&&x.student!=='Aluno de demonstração').length,'pen','rose')}</div>
      <div class="two-cols"><div class="panel"><h2 class="section-title">Progresso por curso</h2>${state.courses.filter(c=>state.enrollments.includes(c.id)).map(c=>`<div style="margin-top:22px"><div class="section-head" style="margin-bottom:7px"><b style="font-size:12px">${esc(c.title)}</b><small>${courseProgress(c)}%</small></div><div class="progress-track"><div class="progress-fill" style="width:${courseProgress(c)}%"></div></div></div>`).join('')}</div><div class="panel"><h2 class="section-title">Aproveitamento nos quizzes</h2>${completed.length?`<div class="mini-chart" style="margin-top:27px">${completed.slice(-9).map(r=>`<div class="mini-bar" style="height:${Math.max(8,r.pct)}%" title="${esc(r.category)}: ${r.pct}%"></div>`).join('')}</div><p class="muted" style="margin-top:15px">Últimas ${Math.min(9,completed.length)} avaliações realizadas.</p>`:empty('Seu gráfico aparecerá aqui','Responda a um quiz para iniciar seu histórico.')}</div></div>`;}
  const plansData=[['Básico',19.9,'O primeiro passo para estudar com organização.',['Perfil do aluno','Plano de estudos','Videoaulas introdutórias','Questões essenciais']],['Plus',49.9,'Aprofunde os conteúdos e acompanhe sua evolução.',['Tudo do Básico','Cursos selecionados','Simulados e estatísticas','Tarefas avaliativas']],['Prime',89.9,'Sua experiência mais completa com o Prof. Rafa Boni.',['Tudo do Plus','Biblioteca de cursos incluídos','Correções individuais com limite definido','Encontros coletivos programados']]];
  function plans(){return `${hTop('SUA ASSINATURA','Um plano para cada objetivo','Escolha o universo de aprendizagem que combina com você.')}
      <div class="plan-grid">${plansData.map(([name,price,desc,features])=>`<div class="plan-card ${name==='Prime'?'highlight':''}">${name==='Prime'?'<span class="ribbon">MAIS COMPLETO</span>':''}<span class="plan-label">BONIVERSO ${name.toUpperCase()}</span><h2>${esc(name)}</h2><div class="plan-price">${money(price)} <small>/mês</small></div><p>${esc(desc)}</p>${features.map(f=>`<div class="plan-feature">${ic('check',17)}<span>${esc(f)}</span></div>`).join('')}<button class="btn ${state.plan===name?'btn-outline':name==='Prime'?'btn-gold':''}" data-action="choose-plan" data-id="${name}">${state.plan===name?'Plano selecionado (demo)':'Simular escolha do plano'}</button></div>`).join('')}</div>
      <div class="callout warn section">${ic('lock',18)} <b>Sem cobrança nesta versão.</b> Planos e preços são ilustrativos. Cadastro de cartão e assinatura recorrente exigem integração segura com provedor de pagamentos e regras das lojas.</div>`;}
  function profile(){return `${hTop('CONFIGURAÇÕES','Meu perfil','Personalize o seu espaço no BoniVerso.')}
    <div class="two-cols"><div class="panel"><h2 class="section-title">Dados do estudante</h2><form id="profileForm" style="margin-top:20px"><div class="form-field"><label for="profileName">Nome de exibição</label><input id="profileName" name="name" value="${esc(state.name)}" maxlength="80" required/></div><div class="form-field"><label for="profileEmail">E-mail de contato (apenas demonstração)</label><input id="profileEmail" type="email" name="email" value="${esc(state.email)}" placeholder="aluno@exemplo.com"/></div><div class="form-field"><label>Plano selecionado</label><input value="BoniVerso ${esc(state.plan)} · demonstração" disabled/></div><button class="btn" type="submit">${ic('save')} Salvar perfil local</button></form></div><div class="panel"><div class="persona-panel"><img src="rafa-boni.jpg" alt="Prof. Rafael Bonifácio"/><div><h2 class="section-title">Bem-vindo ao BoniVerso</h2><p class="muted">Um universo de aprendizado guiado pelo Prof. Rafa Boni.</p></div></div><div class="callout section">${ic('info',18)} <b>Privacidade:</b> informações inseridas nesta prévia ficam armazenadas neste navegador. Não crie senhas nem informe dados sensíveis.</div><div class="section"><button class="btn btn-outline" data-action="switch-role">${ic('people')} ${state.role==='teacher'?'Voltar para área do aluno':'Visualizar painel do professor'}</button></div><div class="section"><button class="btn btn-outline" data-action="reset-demo">Restaurar dados de demonstração</button></div></div></div>`;}
  function admin(){return `${teacherBanner()}${hTop('PAINEL DO PROFESSOR','Boa aula, Prof. Rafa Boni!','Gerencie sua plataforma e acompanhe as atividades demonstrativas.',btn('Adicionar curso','new-course','','plus'))}
      <div class="hero" style="height:205px"><div class="hero-orbit"></div><div class="hero-copy"><div class="hero-eyebrow">INSTITUTO RSB EDUCAÇÃO</div><h1 style="font-size:29px">Ensinar transforma <em>futuros.</em></h1><p>Publique suas aulas e organize a jornada de aprendizagem dos seus alunos.</p></div><img class="hero-portrait" src="rafa-boni-cutout.png" alt="Prof. Rafael Bonifácio"/></div>
      <div class="stats-row">${stat('Cursos cadastrados',state.courses.length,'book','blue')}${stat('Aulas criadas',state.courses.reduce((n,c)=>n+c.lessons.length,0),'play','green')}${stat('Atividades',state.assignments.length,'clipboard','gold')}${stat('Para corrigir',state.submissions.filter(s=>s.status!=='graded').length,'pen','rose')}</div>
      <div class="two-cols"><div class="panel"><div class="section-head"><h2 class="section-title">Cursos e aulas</h2><button class="link-action" data-action="manage-courses">Gerenciar tudo ${ic('arrow',13)}</button></div>${state.courses.slice(-4).reverse().map(c=>`<div class="task-row"><div class="stat-icon blue">${ic('book')}</div><div class="task-detail"><strong>${esc(c.title)}</strong><small>${c.lessons.length} aulas · ${esc(c.category)}</small></div><button class="btn btn-sm btn-outline" data-action="course" data-id="${esc(c.id)}">Ver</button></div>`).join('')}</div><div class="panel"><div class="section-head"><h2 class="section-title">Redações para avaliar</h2><button class="link-action" data-action="corrections">Ver correções ${ic('arrow',13)}</button></div>${state.submissions.filter(s=>s.status!=='graded').slice(0,4).map(s=>submissionCard(s,true)).join('')||empty('Nenhuma redação pendente','As redações recebidas aparecerão aqui.')}</div></div>`;}
  function manageCourses(){return `${teacherBanner()}${hTop('BIBLIOTECA DO PROFESSOR','Gerenciar cursos','Cadastre cursos e organize conteúdos e videoaulas.',btn('Criar novo curso','new-course','','plus'))}<div class="course-grid">${state.courses.map(c=>`<article class="course-card">${courseArt(c)}<div class="course-content"><small>${esc(c.category)}</small><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="course-meta"><span>${ic('play')} ${c.lessons.length} aulas</span></div><div class="course-footer">${chip(money(c.price),'gold')}<button class="btn btn-sm" data-action="course" data-id="${esc(c.id)}">Editar aulas ${ic('chevron',14)}</button></div></div></article>`).join('')}</div>`;}
  function manageTasks(){return `${teacherBanner()}${hTop('AVALIAÇÕES','Atividades e prazos','Crie propostas com prazo e pontuação.',btn('Nova atividade','new-assignment','','plus'))}<div class="panel"><div class="site-table-wrap"><table class="small-table"><thead><tr><th>Atividade</th><th>Categoria</th><th>Prazo</th><th>Nota máxima</th><th></th></tr></thead><tbody>${state.assignments.map(a=>`<tr><td><strong>${esc(a.title)}</strong><br/><span class="muted">${esc(a.description)}</span></td><td>${esc(a.category)}</td><td>${dateBR(a.due)}</td><td>${a.points}</td><td><button class="btn btn-sm btn-outline" data-action="edit-assignment" data-id="${esc(a.id)}">Editar</button></td></tr>`).join('')}</tbody></table></div></div>`;}
  function corrections(){return `${teacherBanner()}${hTop('CORREÇÃO','Oficina de redação','Avalie os textos e registre feedback e notas.')}${state.submissions.length?`<div class="two-cols">${state.submissions.map(s=>submissionCard(s,true)).join('')}</div>`:empty('Ainda não há entregas','Quando um estudante enviar uma redação, ela aparecerá aqui.')}`;}
  function students(){return `${teacherBanner()}${hTop('ACOMPANHAMENTO','Estudantes','Visualização de exemplo; dados reais serão exibidos após a integração de contas.')}<div class="panel"><div class="callout">${ic('info',18)} <b>Dados fictícios de demonstração.</b> Nenhum estudante real está cadastrado neste protótipo.</div><div class="site-table-wrap section"><table class="small-table"><thead><tr><th>Aluno</th><th>Plano</th><th>Progresso</th><th>Situação</th></tr></thead><tbody><tr><td>Aluno de demonstração</td><td>Básico (simulado)</td><td>25%</td><td>${chip('Exemplo','gold')}</td></tr><tr><td>${esc(state.name)}</td><td>${esc(state.plan)} (simulado)</td><td>${pct(countDone(),state.tasks.length)}%</td><td>${chip('Perfil local','green')}</td></tr></tbody></table></div></div>`;}
  function finance(){return `${teacherBanner()}${hTop('NEGÓCIO','Planos e vendas','Estruture suas assinaturas e os cursos avulsos.')}<div class="stats-row">${stat('Vendas reais','—','credit','gold')}${stat('Assinaturas reais','—','people','blue')}${stat('Receita confirmada','R$ 0','chart','green')}${stat('Método de pagamento','Pendente','lock','rose')}</div><div class="panel"><h2 class="section-title">Planos comerciais propostos</h2><div class="site-table-wrap"><table class="small-table"><thead><tr><th>Plano</th><th>Valor indicativo</th><th>Status</th></tr></thead><tbody>${plansData.map(p=>`<tr><td>BoniVerso ${p[0]}</td><td>${money(p[1])}/mês</td><td>${chip('Não publicado','gold')}</td></tr>`).join('')}</tbody></table></div><div class="callout warn section">${ic('lock',18)} Nenhuma cobrança ou assinatura está ativa. Para vender, precisamos de autenticação, controle de permissões, integração com pagamentos, webhooks seguros, termos e política de privacidade.</div></div>`;}
  function renderCourseDetail(id){const c=state.courses.find(x=>x.id===id);if(!c) return toast('Curso não encontrado.');const owned=state.enrollments.includes(c.id),p=courseProgress(c);openDialog(`<div class="dialog-head"><div><div class="eyebrow">${esc(c.category)}</div><h2>${esc(c.title)}</h2><p>${esc(c.description)}</p></div>${closeBtn()}</div><div class="course-detail-cover" style="--art1:${cssColors[c.color%5][0]};--art2:${cssColors[c.color%5][1]};--art3:${cssColors[c.color%5][2]}">${ic('book',50)}</div><div class="section-head"><strong>${c.lessons.length} aulas · ${esc(c.duration)}</strong>${chip(owned?p+'% concluído':money(c.price),owned?'green':'gold')}</div>${c.lessons.map((l,i)=>`<div class="lesson-row"><div class="lesson-icon">${ic('play')}</div><div><strong>${i+1}. ${esc(l.title)}</strong><small>${esc(l.duration||'Duração a definir')} ${state.completed.includes(l.id)?'· Concluída ✓':''} ${l.resources?.length?'· '+l.resources.length+' material(is)':''}</small></div><button class="btn btn-sm btn-outline" data-action="lesson" data-id="${esc(c.id)}::${esc(l.id)}">${state.role==='teacher'?'Editar':'Abrir'}</button></div>`).join('')}${state.role==='teacher'?`<div class="dialog-actions">${btn('Adicionar aula','add-lesson','','plus')}${btn('Editar curso','edit-course','btn-outline','edit')}</div>`:!owned?`<div class="dialog-actions">${btn('Experimentar curso na prévia','enroll','','check')}</div>`:''}<div class="callout section">${ic('info',18)} Prévia de conteúdo: videoaulas reais serão adicionadas pelo professor. Sem pagamento nesta versão.</div>`,{courseId:c.id});}
  function closeBtn(){return `<button type="button" class="dialog-close" data-action="close-dialog" aria-label="Fechar">${ic('close')}</button>`;}
  let modalCtx={};
  function openDialog(content,ctx={}){modalCtx=ctx;$('#dialogContents').innerHTML=`<div class="dialog-inner">${content}</div>`;$('#dialog').showModal();}
  function closeDialog(){if($('#dialog').open)$('#dialog').close();}
  const field = (label,name,value='',type='text',required=true,other='')=>`<div class="form-field"><label for="f_${esc(name)}">${esc(label)}</label><input id="f_${esc(name)}" name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" ${required?'required':''} ${other}/></div>`;
  const textArea = (label,name,value='',required=true,extra='')=>`<div class="form-field"><label for="f_${name}">${esc(label)}</label><textarea id="f_${name}" name="${name}" ${required?'required':''} ${extra}>${esc(value)}</textarea></div>`;
  const formDialog = (title,sub,html,formId,submitText='Salvar') => openDialog(`<div class="dialog-head"><div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div>${closeBtn()}</div><form id="${formId}">${html}<div class="dialog-actions"><button class="btn btn-outline" type="button" data-action="close-dialog">Cancelar</button><button class="btn" type="submit">${ic('check')}${esc(submitText)}</button></div></form>`);
  function lessonDialog(courseId,lessonId){const c=state.courses.find(c=>c.id===courseId),l=c?.lessons.find(l=>l.id===lessonId);if(!l)return;modalCtx={courseId,lessonId};const watch=l.videoUrl?videoMarkup(l.videoUrl):`<div class="callout">${ic('info',18)} Videoaula ainda não publicada. O professor poderá inserir um vídeo hospedado em serviço apropriado.</div>`;openDialog(`<div class="dialog-head"><div><div class="eyebrow">${esc(c.title)}</div><h2>${esc(l.title)}</h2><p>${esc(l.duration||'Aula gravada')}</p></div>${closeBtn()}</div>${watch}<div class="section" style="margin-top:21px"><h3 class="section-title">Materiais da aula</h3>${(l.resources||[]).length?l.resources.map(r=>`<div class="lesson-row"><span class="lesson-icon">${ic('file')}</span><div><strong>${esc(r.name)}</strong><small>Arquivo da aula</small></div><button class="btn btn-sm btn-outline" data-action="download-file" data-id="${esc(r.id)}">${ic('download')}</button></div>`).join(''):empty('Sem materiais nesta aula','O professor poderá anexar arquivos PDF, DOC ou DOCX.')}</div><div class="dialog-actions">${state.role==='teacher'?`${btn('Editar aula','edit-lesson','btn-outline','edit')}${btn('Enviar arquivo','add-resource','','upload')}`:`${btn(state.completed.includes(l.id)?'Já concluída':'Marcar como concluída','complete-lesson',state.completed.includes(l.id)?'btn-outline':'','check')}`}</div>`,{courseId,lessonId});}
  function videoMarkup(url){try{const u=new URL(url);if(!['https:'].includes(u.protocol))throw Error();let videoId='';if(['www.youtube.com','youtube.com','m.youtube.com'].includes(u.hostname)) videoId=u.searchParams.get('v')||u.pathname.match(/^\/shorts\/([\w-]+)/)?.[1];if(u.hostname==='youtu.be') videoId=u.pathname.slice(1);if(videoId&&/^[\w-]{8,15}$/.test(videoId)) return `<iframe title="Videoaula" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen src="https://www.youtube-nocookie.com/embed/${videoId}"></iframe>`;if(u.hostname.endsWith('vimeo.com')){const id=u.pathname.split('/').filter(Boolean).pop();if(/^\d+$/.test(id))return `<iframe title="Videoaula" loading="lazy" allowfullscreen src="https://player.vimeo.com/video/${id}"></iframe>`;}return `<div class="callout">${ic('play',20)} Vídeo hospedado externamente. <a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer" style="text-decoration:underline">Abrir a videoaula ${ic('external',15)}</a></div>`;}catch{return '<div class="callout warn">URL de vídeo inválida. Edite a aula para corrigir.</div>';}}
  function gradeDialog(id){const s=state.submissions.find(s=>s.id===id);if(!s)return;const a=state.assignments.find(a=>a.id===s.assignmentId);const competencies=s.competencies||[0,0,0,0,0];openDialog(`<div class="dialog-head"><div><div class="eyebrow">CORREÇÃO DE REDAÇÃO</div><h2>${esc(a?.title||'Redação')}</h2><p>Entrega de ${esc(s.student)} · ${dateBR(s.sent)}</p></div>${closeBtn()}</div><div class="callout" style="max-height:180px;overflow:auto;white-space:pre-wrap">${esc(s.text)}</div><form id="gradeForm" data-id="${esc(s.id)}" style="margin-top:17px"><p class="muted">Atribua de 0 a 200 pontos por competência (passos de 40). Critérios ilustrativos, sem cálculo automático de nota pedagógica.</p><div class="form-row">${competencies.map((p,i)=>`<div class="form-field"><label>Competência ${i+1}</label><select name="c${i+1}">${[0,40,80,120,160,200].map(n=>`<option value="${n}" ${Number(p)===n?'selected':''}>${n} pontos</option>`).join('')}</select></div>`).join('')}</div>${textArea('Feedback individual ao estudante','feedback',s.feedback||'',true)}<div class="dialog-actions"><button type="button" class="btn btn-outline" data-action="close-dialog">Cancelar</button><button type="submit" class="btn">${ic('save')} Salvar avaliação</button></div></form>`,{submissionId:id});}
  function makeCourseForm(id=null){const c=state.courses.find(x=>x.id===id),cats=['Redação','Língua Portuguesa','Literatura','Gramática','Outros'];formDialog(c?'Editar curso':'Criar um curso','Preencha as informações exibidas aos estudantes.',`${field('Nome do curso','title',c?.title||'')}${textArea('Descrição','description',c?.description||'')}<div class="form-row"><div class="form-field"><label>Disciplina</label><select name="category">${cats.map(o=>`<option ${c?.category===o?'selected':''}>${o}</option>`).join('')}</select></div>${field('Valor avulso sugerido (R$)','price',c?.price||99.9,'number',true,'min="0" step="0.01"')}</div><div class="form-row">${field('Carga horária estimada','duration',c?.duration||'4 horas')}${field('Nível','level',c?.level||'Todos os níveis')}</div>`, 'courseForm',c?'Salvar alterações':'Criar curso');modalCtx={courseId:id};}
  function makeLessonForm(courseId,id=null){const c=state.courses.find(x=>x.id===courseId),l=c?.lessons.find(x=>x.id===id);formDialog(l?'Editar aula':'Adicionar videoaula',`Curso: ${c?.title||''}`,`${field('Título da aula','title',l?.title||'')}${field('Duração (ex.: 25 min)','duration',l?.duration||'25 min')}${field('URL de vídeo (YouTube, Vimeo ou HTTPS)','videoUrl',l?.videoUrl||'','url',false,'placeholder="https://..."')}<div class="callout">${ic('info',16)} Esta prévia grava somente o link da aula. Para cursos pagos, precisaremos de hospedagem com controle de acesso ao vídeo.</div>`, 'lessonForm',l?'Salvar aula':'Publicar aula (demo)');modalCtx={courseId,lessonId:id};}
  function makeTaskForm(){formDialog('Nova tarefa','Organize seus estudos com pequenas metas.',`${field('O que você vai estudar?','title','')}${field('Data de entrega','due',inDays(2),'date')}${field('Disciplina','category','Redação')}`,'taskForm','Adicionar tarefa');}
  function makeAssignmentForm(id=null){const a=state.assignments.find(x=>x.id===id);formDialog(a?'Editar atividade':'Criar atividade','Defina um prazo e uma orientação para os alunos.',`${field('Título da atividade','title',a?.title||'')}${textArea('Enunciado / orientações','description',a?.description||'')}${field('Categoria','category',a?.category||'Redação')}<div class="form-row">${field('Prazo de entrega','due',a?.due||inDays(7),'date')}${field('Nota máxima','points',a?.points||1000,'number',true,'min="1" step="1"')}</div>`,'assignmentForm');modalCtx={assignmentId:id};}
  function makeEssayForm(assignmentId=null){const a=state.assignments.find(x=>x.id===assignmentId);formDialog('Enviar redação',a?.title||'Oficina de redação',`<div class="form-field"><label>Proposta</label><select name="assignmentId">${state.assignments.map(x=>`<option value="${esc(x.id)}" ${x.id===assignmentId?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div>${textArea('Digite sua redação','text','',true,'minlength="50" rows="11"')}<div class="callout">${ic('info',16)} Este envio fica apenas no seu navegador. Não existe transmissão de dados para o professor nesta demonstração.</div>`, 'essayForm','Entregar redação (demo)');}
  function openQuiz(category){const questions=state.quizzes.filter(q=>category==='Todas'||q.category===category);if(!questions.length)return toast('Não há questões nesta disciplina.');activeQuiz={category,questions,answers:{},idx:0};quizDialog();}
  function quizDialog(){if(!activeQuiz)return;const {questions,idx,answers}=activeQuiz,q=questions[idx];const chosen=answers[q.id];openDialog(`<div class="dialog-head"><div><div class="eyebrow">${esc(activeQuiz.category)} · QUESTÃO ${idx+1}/${questions.length}</div><h2>Hora de praticar!</h2><p>Escolha a alternativa correta e avance.</p></div>${closeBtn()}</div><form id="quizForm" data-qid="${esc(q.id)}"><p style="font-weight:650;line-height:1.7">${esc(q.q)}</p>${q.options.map((o,i)=>`<label class="quiz-option"><input type="radio" name="answer" value="${i}" ${chosen===i?'checked':''} required/> ${esc(String.fromCharCode(65+i)+') '+o)}</label>`).join('')}<div class="dialog-actions"><button class="btn" type="submit">${idx===questions.length-1?'Finalizar quiz':'Próxima questão'} ${ic('arrow')}</button></div></form>`);}
  function quizFinish(){const quiz=activeQuiz;if(!quiz)return;const correct=quiz.questions.filter(q=>quiz.answers[q.id]===q.answer).length;const result={id:uid(),category:quiz.category,correct,total:quiz.questions.length,pct:pct(correct,quiz.questions.length),date:inDays(0)};state.quizResults.push(result);save();activeQuiz=null;openDialog(`<div class="dialog-head"><div><div class="eyebrow">QUIZ CONCLUÍDO</div><h2>Você acertou ${correct} de ${result.total}!</h2><p>Seu resultado: ${result.pct}% de aproveitamento.</p></div>${closeBtn()}</div><div class="quiz-result">${ic('award',23)} Continue praticando! Cada exercício reforça seu conhecimento.</div><h3 class="section-title section">Gabarito comentado</h3>${quiz.questions.map((q,i)=>`<div class="submission-card"><strong>${i+1}. ${esc(q.q)}</strong><p style="margin-top:6px">Resposta correta: <b>${esc(q.options[q.answer])}</b></p><p style="margin-top:5px">${esc(q.explain)}</p>${quiz.answers[q.id]===q.answer?chip('Você acertou!','green'):chip('Revise o conteúdo','gold')}</div>`).join('')}<div class="dialog-actions">${btn('Concluir','close-dialog','','check')}</div>`);render();}
  async function filesDb(){return new Promise((res,rej)=>{if(!window.indexedDB)return rej(Error('IndexedDB indisponível'));let rq=indexedDB.open('boniverso-demo-files',1);rq.onupgradeneeded=()=>{rq.result.createObjectStore('files',{keyPath:'id'});};rq.onerror=()=>rej(rq.error);rq.onsuccess=()=>res(rq.result);});}
  async function storeFile(file){const db=await filesDb();return new Promise((res,rej)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put({id:uid(),blob:file,name:file.name,type:file.type});tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error);});}
  async function getFile(id){const db=await filesDb();return new Promise((res,rej)=>{const tx=db.transaction('files','readonly');const rq=tx.objectStore('files').get(id);rq.onsuccess=()=>res(rq.result);rq.onerror=()=>rej(rq.error);});}
  function filePickerDialog(){openDialog(`<div class="dialog-head"><div><h2>Adicionar material à aula</h2><p>Aceita PDF, Word (.doc ou .docx) — máximo 15 MB por arquivo.</p></div>${closeBtn()}</div><form id="resourceForm"><div class="form-field"><label for="resourceFile">Escolha um arquivo</label><input type="file" id="resourceFile" name="resource" accept=".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document" required/></div><div class="callout warn">${ic('info',17)} Material salvo apenas neste dispositivo, não disponível para outros alunos. Arquivos publicados de verdade exigem armazenamento remoto protegido.</div><div class="dialog-actions"><button type="submit" class="btn">${ic('upload')} Adicionar arquivo</button></div></form>`,modalCtx);}
  function render(){const teacher=state.role==='teacher';const menu=menuForRole();if(!menu.some(m=>m[0]===state.view))state.view=teacher?'admin':'home';$('#sideNav').innerHTML=menu.map(([key,title,icon])=>`<button class="nav-link ${key===state.view?'active':''}" data-action="navigate" data-id="${key}">${ic(icon)} ${esc(title)}</button>`).join('');$('#mobileBottom').innerHTML=(teacher?[["admin","Início","home"],["manage-courses","Cursos","book"],["corrections","Correções","pen"],["finance","Vendas","credit"],["profile","Perfil","profile"]]:[["home","Início","home"],["courses","Cursos","book"],["planner","Plano","calendar"],["performance","Evolução","chart"],["profile","Perfil","profile"]]).map(([key,title,icon])=>`<button class="mobile-nav-link ${state.view===key?'active':''}" data-action="navigate" data-id="${key}">${ic(icon)}<span>${title}</span></button>`).join('');$('#profileSwitch').innerHTML=`<div class="avatar-small">${teacher?'<img src="rafa-boni.jpg" alt="Rafael"/>':esc(state.name.charAt(0).toUpperCase())}</div><div class="profile-info"><b>${teacher?'Prof. Rafa Boni':esc(state.name)}</b><small>${teacher?'Editor (simulação)':`Plano ${esc(state.plan)} · demo`}</small></div><button title="Alternar perfil de demonstração" aria-label="Alternar perfil" data-action="switch-role">${ic('settings')}</button>`;$('#topAvatar').innerHTML=teacher?'<img src="rafa-boni.jpg" alt="Professor" style="width:100%;height:100%;object-fit:cover">':esc(state.name.charAt(0).toUpperCase());$('#breadcrumb').textContent=viewTitle();$('#topGreeting').innerHTML=teacher?'Olá, professor <span>✦</span>':'Olá, estudante <span>✦</span>';$('#thisYear').textContent=TODAY.getFullYear();const views={home,courses,planner,quizzes,essays,performance,plans,profile,admin,'manage-courses':manageCourses,'manage-tasks':manageTasks,corrections,students,finance};$('#view').innerHTML=views[state.view]();$('#sidebar').classList.remove('open');$('#shade').classList.remove('visible');}
  function nav(to){closeDialog();state.view=to;save();render();window.scrollTo({top:0,behavior:'instant'});}
  document.addEventListener('click', async ev=>{
    const el=ev.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id||'';
    if(action==='navigate')return nav(id);
    if(action==='go-courses'||action==='manage-courses')return nav(state.role==='teacher'?'manage-courses':'courses');
    if(action==='go-planner')return nav('planner');if(action==='go-performance')return nav('performance');if(action==='corrections')return nav('corrections');
    if(action==='close-dialog')return closeDialog();
    if(action==='course')return renderCourseDetail(id);
    if(action==='lesson'){const [c,l]=id.split('::');return lessonDialog(c,l);}
    if(action==='filter'){courseFilter=id;return render();}
    if(action==='new-task')return makeTaskForm();
    if(action==='new-essay'||action==='essay-for')return makeEssayForm(id||null);
    if(action==='new-course')return makeCourseForm();
    if(action==='edit-course')return makeCourseForm(modalCtx.courseId);
    if(action==='add-lesson')return makeLessonForm(modalCtx.courseId);
    if(action==='edit-lesson')return makeLessonForm(modalCtx.courseId,modalCtx.lessonId);
    if(action==='add-resource')return filePickerDialog();
    if(action==='edit-assignment')return makeAssignmentForm(id);
    if(action==='new-assignment')return makeAssignmentForm();
    if(action==='grade')return gradeDialog(id);
    if(action==='start-quiz')return openQuiz(id);
    if(action==='complete-lesson'){update(()=>{const l=modalCtx.lessonId;if(!state.completed.includes(l))state.completed.push(l);});closeDialog();return toast('Aula marcada como concluída!');}
    if(action==='enroll'){update(()=>state.enrollments.push(modalCtx.courseId));closeDialog();return toast('Curso liberado apenas nesta demonstração.');}
    if(action==='choose-plan'){update(()=>state.plan=id);return toast(`Plano ${id} selecionado para demonstração. Nenhuma cobrança foi realizada.`);}
    if(action==='switch-role'){closeDialog();state.role=state.role==='teacher'?'student':'teacher';return nav(state.role==='teacher'?'admin':'home');}
    if(action==='reset-demo'){if(confirm('Restaurar a demonstração? Isso apaga seu progresso e alterações locais (arquivos enviados ao navegador não são apagados).')) {state=initial();save();nav('home');toast('Dados demonstrativos restaurados.');}return;}
    if(action==='download-file'){try{const item=await getFile(id);if(!item)return toast('Arquivo não encontrado neste navegador.');const url=URL.createObjectURL(item.blob);const link=document.createElement('a');link.href=url;link.download=item.name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}catch(e){toast('Falha ao abrir arquivo local.');}return;}
  });
  document.addEventListener('change',ev=>{if(ev.target.matches('[data-task]')){const t=state.tasks.find(t=>t.id===ev.target.dataset.task);if(t){t.done=ev.target.checked;save();render();toast(t.done?'Tarefa concluída!':'Tarefa reaberta.');}}});
  document.addEventListener('input',ev=>{if(ev.target.id==='courseSearch'){searchValue=ev.target.value;const pos=ev.target.selectionStart;render();const input=$('#courseSearch');input.focus();input.setSelectionRange(pos,pos);}});
  document.addEventListener('submit', async ev=>{
    const f=ev.target;if(!f.id)return;ev.preventDefault();const data=Object.fromEntries(new FormData(f));
    if(f.id==='profileForm'){state.name=String(data.name||'Estudante').trim().slice(0,80);state.email=String(data.email||'').trim().slice(0,150);save();render();return toast('Perfil atualizado neste dispositivo.');}
    if(f.id==='taskForm'){state.tasks.push({id:uid(),title:String(data.title).trim().slice(0,150),due:data.due,done:false,category:String(data.category||'Estudos').slice(0,50)});save();closeDialog();render();return toast('Tarefa adicionada ao planejamento!');}
    if(f.id==='courseForm'){const id=modalCtx.courseId;let c=state.courses.find(c=>c.id===id);if(!c){c={id:uid(),lessons:[],color:state.courses.length%5};state.courses.push(c);}Object.assign(c,{title:String(data.title).trim().slice(0,120),description:String(data.description).trim().slice(0,500),category:String(data.category),price:Math.max(0,Number(data.price)),level:String(data.level).slice(0,90),duration:String(data.duration).slice(0,40)});save();closeDialog();render();return toast('Curso salvo na prévia local.');}
    if(f.id==='lessonForm'){const c=state.courses.find(x=>x.id===modalCtx.courseId);if(!c)return;let l=c.lessons.find(l=>l.id===modalCtx.lessonId);if(!l){l={id:uid(),resources:[]};c.lessons.push(l);}Object.assign(l,{title:String(data.title).trim().slice(0,120),duration:String(data.duration).trim().slice(0,30),videoUrl:String(data.videoUrl||'').trim().slice(0,500)});save();closeDialog();render();return toast('Aula registrada.');}
    if(f.id==='assignmentForm'){let a=state.assignments.find(a=>a.id===modalCtx.assignmentId);if(!a){a={id:uid()};state.assignments.push(a);}Object.assign(a,{title:String(data.title).trim().slice(0,150),description:String(data.description).trim().slice(0,2000),category:String(data.category).trim().slice(0,80),due:data.due,points:Number(data.points)});save();closeDialog();render();return toast('Atividade salva para demonstração.');}
    if(f.id==='essayForm'){const text=String(data.text||'').trim();if(text.length<50)return toast('Digite pelo menos 50 caracteres.');state.submissions.push({id:uid(),student:state.name,assignmentId:data.assignmentId,text,sent:inDays(0),status:'pending',grade:null,feedback:'',competencies:[0,0,0,0,0]});save();closeDialog();render();return toast('Redação registrada neste navegador!');}
    if(f.id==='gradeForm'){const sub=state.submissions.find(s=>s.id===f.dataset.id);if(!sub)return;const scores=[1,2,3,4,5].map(n=>Number(data['c'+n]||0));sub.competencies=scores;sub.grade=scores.reduce((a,b)=>a+b,0);sub.feedback=String(data.feedback||'').slice(0,5000);sub.status='graded';save();closeDialog();render();return toast('Correção registrada neste navegador.');}
    if(f.id==='quizForm'){const qid=f.dataset.qid;activeQuiz.answers[qid]=Number(data.answer);if(activeQuiz.idx<activeQuiz.questions.length-1){activeQuiz.idx++;quizDialog();}else quizFinish();return;}
    if(f.id==='resourceForm'){const file=f.querySelector('input[type=file]').files[0];if(!file)return;const ext=file.name.split('.').pop().toLowerCase();if(!['pdf','doc','docx'].includes(ext)||file.size>15*1024*1024){return toast('Envie um PDF ou Word de até 15 MB.');}const newId=uid();try{const db=await filesDb();await new Promise((res,rej)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put({id:newId,name:file.name,type:file.type,blob:file});tx.oncomplete=res;tx.onerror=()=>rej(tx.error);});const c=state.courses.find(c=>c.id===modalCtx.courseId),l=c?.lessons.find(l=>l.id===modalCtx.lessonId);if(!l)throw Error();l.resources.push({id:newId,name:file.name});save();lessonDialog(c.id,l.id);toast('Arquivo adicionado apenas neste dispositivo.');}catch(e){toast('Não foi possível salvar o arquivo neste navegador.');}return;}
  });
  $('#menuToggle').addEventListener('click',()=>{$('#sidebar').classList.toggle('open');$('#shade').classList.toggle('visible');});
  $('#shade').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#shade').classList.remove('visible');});
  $('#searchButton').addEventListener('click',()=>{nav('courses');$('#courseSearch')?.focus();});
  $('#notifications').addEventListener('click',()=>toast('Você está usando uma prévia. Avisos reais serão ativados na plataforma online.'));
  $('#topAvatar').addEventListener('click',()=>nav('profile'));
  if('serviceWorker' in navigator && (location.protocol==='https:'||location.hostname==='localhost')) window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
  document.querySelectorAll('[data-icon]').forEach(el => { el.innerHTML = ic(el.dataset.icon); });
  render();
})();
